const baseUrl = String($env.WEBHOOK_URL || '').replace(/\/$/, '');
const n8nInternal = String($env.N8N_INTERNAL_URL || baseUrl || ('http://n8n:' + ($env.N8N_PORT || '5678'))).replace(/\/$/, '');
const n8nApiKey = $env.N8N_API_KEY || '';
const summary = {
  workflows_activated: [],
  telegram: [],
  discord: null,
  mongodb: null,
  knowledge_seeded: 0,
  white_label_brand: $env.BRAND_NAME || 'Tradesejon'
};

// 1. Auto-publish any inactive modular workflows if N8N_API_KEY is configured
if (n8nApiKey) {
  try {
    const listRes = await fetch(`${n8nInternal}/api/v1/workflows?limit=200`, {
      headers: { 'X-N8N-API-KEY': n8nApiKey }
    }).then(r => r.json());
    for (const w of (listRes.data || [])) {
      if (!w.active && !String(w.name || '').startsWith('Template_')) {
        await fetch(`${n8nInternal}/api/v1/workflows/${w.id}/activate`, {
          method: 'POST', headers: { 'X-N8N-API-KEY': n8nApiKey }
        }).catch(() => null);
        summary.workflows_activated.push(w.name);
      }
    }
  } catch (e) {}
}

// 2. Probe whether individual webhook is published; fall back gracefully to /webhook/tradesejon-unified if unpublished
async function resolveTargetWebhookPath(preferredPath) {
  try {
    const probe = await fetch(`${n8nInternal}/webhook/${preferredPath}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ _probe: true })
    });
    if (probe.status !== 404) return preferredPath;
  } catch (e) {}
  return 'tradesejon-unified';
}

for (const [label, tok, preferredPath] of [
  ['CEO_BOT', $env.TELEGRAM_CEO_BOT_TOKEN, 'tradesejon-ceo'],
  ['PR_BOT', $env.TELEGRAM_PR_BOT_TOKEN, 'tradesejon-pr'],
  ['TRADER_BOT', $env.TELEGRAM_TRADER_BOT_TOKEN, 'tradesejon-trader']
]) {
  if (!tok || !baseUrl) {
    summary.telegram.push({ bot: label, ok: false, error: 'Missing token or WEBHOOK_URL' });
    continue;
  }
  const resolvedPath = await resolveTargetWebhookPath(preferredPath);
  try {
    const res = await fetch(`https://api.telegram.org/bot${tok}/setWebhook?url=${encodeURIComponent(baseUrl + '/webhook/' + resolvedPath)}`).then(r => r.json());
    summary.telegram.push({ bot: label, ok: Boolean(res.ok), bound_path: resolvedPath, description: res.description });
  } catch (e) {
    summary.telegram.push({ bot: label, ok: false, error: e.message });
  }
}

// 3. Verify Discord Bot Token
const dcTok = $env.DISCORD_BOT_TOKEN || $env.DISCORD_CEO_BOT_TOKEN || '';
if (dcTok) {
  try {
    const dc = await fetch('https://discord.com/api/v10/users/@me', { headers: { 'Authorization': `Bot ${dcTok}` } }).then(r => r.json());
    summary.discord = { ok: Boolean(dc.id), bot_username: dc.username || null };
  } catch (e) { summary.discord = { ok: false, error: e.message }; }
}

// 4. Initialize MongoDB CRM + RAG Knowledge Collections & Seed Disk KB
if ($env.MONGODB_URI) {
  try {
    const { MongoClient } = require('mongodb');
    const fs = require('fs');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    const db = c.db($env.MONGODB_DB || 'tradesejon_prod');
    await Promise.all([
      db.collection('leads').createIndex({ email: 1 }, { unique: true, sparse: true }),
      db.collection('members').createIndex({ discord_user_id: 1 }, { unique: true, sparse: true }),
      db.collection('kb_articles').createIndex({ slug: 1 }, { unique: true, sparse: true }),
      db.collection('knowledge_chunks').createIndex({ slug: 1 }),
      db.collection('audit_logs').createIndex({ timestamp: -1 })
    ]);
    const kbFile = ($env.KB_DIR || '/home/node/rag-knowledge-base') + '/custom_knowledge.json';
    if (fs.existsSync(kbFile)) {
      const parsed = JSON.parse(fs.readFileSync(kbFile, 'utf8'));
      const entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);
      for (const e of entries) {
        if (e.slug && e.content) {
          await db.collection('kb_articles').updateOne({ slug: e.slug }, { $set: { ...e, updated_at: new Date() } }, { upsert: true });
          summary.knowledge_seeded += 1;
        }
      }
    }
    await c.close();
    summary.mongodb = { ok: true, indexes_created: true };
  } catch (e) { summary.mongodb = { ok: false, error: e.message }; }
}

return [{ json: { ok: true, provisioning: summary, timestamp: new Date().toISOString() } }];
